"""JSON syntax support only; no controller schema or domain evaluator."""
import json


def unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def _reject_constant(text):
    raise ValueError('nonfinite number: %s' % text)


def decode(text):
    """Decode one JSON value, rejecting duplicate keys and nonfinite numbers."""
    if not isinstance(text, str):
        raise ValueError('not text')
    if text.startswith('﻿'):
        raise ValueError('byte order mark')
    return json.loads(text, object_pairs_hook=unique,
                      parse_constant=_reject_constant)
