"""Service entry point and import setup.

Reads one JSON request per line from stdin and writes exactly one JSON reply
per line to stdout, keeping all controller state in between.
"""
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))
sys.path.insert(0, '/workspace/vendor/networkx-3.4.2-py3-none-any.whl')

from service import handle
from wire import decode

INVALID = '{"status":"invalid"}'


def main():
    out = sys.stdout
    for raw in sys.stdin.buffer:
        try:
            line = raw.decode('utf-8')
        except UnicodeDecodeError:
            out.write(INVALID)
            out.write('\n')
            out.flush()
            continue
        try:
            request = decode(line)
            response = handle(request)
        except Exception:
            response = {'status': 'invalid'}
        try:
            text = json.dumps(response, separators=(',', ':'))
        except Exception:
            text = INVALID
        out.write(text)
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
